from math import inf
def cheapest_by_provider(rows):
    cheapest = {}
    for row in rows:
        provider, name = row.get("provider"), row.get("name")
        if not provider or not name: raise ValueError("provider and name required")
        try: price = float(row["price"])
        except (KeyError, TypeError, ValueError) as exc: raise ValueError("invalid price") from exc
        if price < 0 or price != price or price in (inf, -inf): raise ValueError("invalid price")
        if provider not in cheapest or (price, name) < (cheapest[provider][0], cheapest[provider][1]): cheapest[provider] = (price, name)
    return {provider: item[1] for provider, item in cheapest.items()}

