def _unique(items): return list(dict.fromkeys(items))
def precision_at_k(results, relevant_ids, k):
    if not isinstance(k, int) or isinstance(k, bool) or k <= 0: return 0.0
    chosen = _unique(results)[:k]
    return sum(item in relevant_ids for item in chosen) / k
def reciprocal_rank(results, relevant_ids):
    for rank, item in enumerate(_unique(results), 1):
        if item in relevant_ids: return 1 / rank
    return 0.0

