def authorize_tool(call, allowed, user_scopes):
    name, request_id = call.get("name"), call.get("request_id")
    if not isinstance(name, str) or name not in allowed: raise PermissionError("tool not allowlisted")
    if not isinstance(request_id, str) or not request_id.strip(): raise PermissionError("request id required")
