def apply_once(event_id, value, store):
    if not isinstance(event_id, str) or not event_id.strip(): raise ValueError("event id required")
    if isinstance(value, bool) or not isinstance(value, (int,float)) or not isfinite(value): raise ValueError("finite numeric value required")
