def evaluation_summary(cases):
    ids = [case.get("id") for case in cases]
    if any(not isinstance(i,str) or not i for i in ids) or len(ids) != len(set(ids)): raise ValueError("case IDs must be unique")
    failures = sorted(case["id"] for case in cases if case.get("expected") != case.get("actual"))
