from math import isfinite
def budget_check(stages, max_latency_ms, max_cost_usd):
    latency=cost=0
    for stage in stages:
        for key in ("latency_ms","cost_usd"):
            value=stage.get(key)
            if isinstance(value,bool) or not isinstance(value,(int,float)) or not isfinite(value) or value<0: raise ValueError("invalid stage estimate")
        latency += stage["latency_ms"]; cost += stage["cost_usd"]
    exceeded=[]
    if latency>max_latency_ms: exceeded.append("latency")
    if cost>max_cost_usd: exceeded.append("cost")
    return {"latency_ms":latency,"cost_usd":round(cost,12),"exceeded":sorted(exceeded)}

