def _validate(code):
    if isinstance(code, bool) or not isinstance(code, int):
        raise ValueError("status code must be an integer")
    return code


def classify_status(code):
    code = _validate(code)
    if 200 <= code <= 299:
        return "success"
    if 300 <= code <= 399:
        return "redirect"
    if 400 <= code <= 499:
        return "client_error"
    if 500 <= code <= 599:
        return "server_error"
    return "unknown"


def retryable(code):
    return _validate(code) in {429, 500, 502, 503, 504}

